use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Where the tokenizer is in the line.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// At the start of a field: a timestamp, a key, or a word follows.
    Start,
    /// Just after `key=`: the value follows.
    Value,
    /// Finished, either at the end of the line or after an error.
    Done,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Start }
    }

    /// Reads the token that starts a field. Returns `None` at the end of the line.
    fn start_token(&mut self) -> Option<Result<Token<'a>, LexError>> {
        let b = self.src.as_bytes();
        let p = skip_blanks(b, self.pos);
        self.pos = p;
        if p == b.len() {
            return None;
        }
        Some(match b[p] {
            b'[' => self.timestamp(p),
            b'"' => Err(LexError::UnexpectedQuote { pos: p }),
            b'=' => Err(LexError::EmptyKey { pos: p }),
            _ => self.key_or_word(p),
        })
    }

    /// Reads `[...]` whose opening bracket is at `open`.
    fn timestamp(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let b = src.as_bytes();
        let start = open + 1;
        let mut close = start;
        loop {
            match b.get(close) {
                None => return Err(LexError::UnterminatedTimestamp { pos: open }),
                Some(b']') => break,
                Some(b'[') => return Err(LexError::NestedBracket { pos: close }),
                Some(_) => close += 1,
            }
        }
        expect_separator(b, close + 1)?;
        self.pos = close + 1;
        Ok(Token::Timestamp(&src[start..close]))
    }

    /// Reads a key, or a word when no `=` follows the run of characters starting at `start`.
    fn key_or_word(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let b = src.as_bytes();
        let end = scan_run(b, start, |c| is_blank(c) || c == b'=')?;
        if b.get(end) == Some(&b'=') {
            self.pos = end + 1;
            self.state = State::Value;
            Ok(Token::Key(&src[start..end]))
        } else {
            self.pos = end;
            Ok(Token::Word(&src[start..end]))
        }
    }

    /// Reads the value that follows `key=`, which ends at `self.pos`.
    fn value(&mut self) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let b = src.as_bytes();
        let p = self.pos;
        self.state = State::Start;
        match b.get(p) {
            None => Ok(Token::Bare(&src[p..p])),
            Some(&c) if is_blank(c) => Ok(Token::Bare(&src[p..p])),
            Some(b'"') => self.quoted(p),
            Some(_) => self.bare(p),
        }
    }

    /// Reads a bare value starting at `start`, which runs up to the next blank.
    fn bare(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let end = scan_run(src.as_bytes(), start, is_blank)?;
        self.pos = end;
        Ok(Token::Bare(&src[start..end]))
    }

    /// Reads a double-quoted value whose opening quote is at `open`.
    fn quoted(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let b = src.as_bytes();
        let start = open + 1;
        let close = closing_quote(b, open)?;
        expect_separator(b, close + 1)?;
        self.pos = close + 1;
        Ok(Token::Quoted(&src[start..close]))
    }
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let item = match self.state {
            State::Start => self.start_token(),
            State::Value => Some(self.value()),
            State::Done => return None,
        };
        if let Some(Err(_)) = item {
            self.state = State::Done;
            self.pos = self.src.len();
        }
        item
    }
}

fn is_blank(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

/// The first index at or after `from` that is not a blank.
fn skip_blanks(b: &[u8], mut from: usize) -> usize {
    while from < b.len() && is_blank(b[from]) {
        from += 1;
    }
    from
}

/// Scans forward from `from` to the first byte that satisfies `ends`, or to the end of the line.
/// A `"` before that point is an error, since quotes may only open a value.
fn scan_run(b: &[u8], mut from: usize, ends: impl Fn(u8) -> bool) -> Result<usize, LexError> {
    while from < b.len() {
        let c = b[from];
        if c == b'"' {
            return Err(LexError::UnexpectedQuote { pos: from });
        }
        if ends(c) {
            break;
        }
        from += 1;
    }
    Ok(from)
}

/// Finds the closing quote of the value opened at `open`, checking its escapes on the way.
fn closing_quote(b: &[u8], open: usize) -> Result<usize, LexError> {
    let mut i = open + 1;
    loop {
        match b.get(i) {
            None => return Err(LexError::UnterminatedQuote { pos: open }),
            Some(b'"') => return Ok(i),
            Some(b'\\') => match b.get(i + 1) {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"' | b'\\' | b'n' | b't') => i += 2,
                Some(_) => return Err(LexError::InvalidEscape { pos: i }),
            },
            Some(_) => i += 1,
        }
    }
}

/// A token must be followed by a blank or the end of the line; `at` is the byte right after it.
fn expect_separator(b: &[u8], at: usize) -> Result<(), LexError> {
    match b.get(at) {
        Some(&c) if !is_blank(c) => Err(LexError::ExpectedSeparator { pos: at }),
        _ => Ok(()),
    }
}

