use std::time::Instant;

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

const ALPHABET: &[&str] = &[
    "[", "]", "\"", "\\", "=", " ", "\t", "a", "n", "t", "1", "é", "\\\"", "\\n", "\\\\", "\\x", "[x]", "k=",
];

fn random_line(rng: &mut Rng) -> String {
    let len = rng.below(14);
    let mut s = String::new();
    for _ in 0..len {
        s.push_str(ALPHABET[rng.below(ALPHABET.len())]);
    }
    s
}

fn collect_orig(line: &str) -> Vec<Result<String, String>> {
    let mut out = Vec::new();
    for item in orig::tokenize(line).take(10_000) {
        out.push(match item {
            Ok(t) => Ok(format!("{t:?}")),
            Err(e) => Err(format!("{e:?}")),
        });
    }
    out
}

fn collect_new(line: &str) -> Vec<Result<String, String>> {
    let mut out = Vec::new();
    for item in new::tokenize(line).take(10_000) {
        out.push(match item {
            Ok(t) => Ok(format!("{t:?}")),
            Err(e) => Err(format!("{e:?}")),
        });
    }
    out
}

fn check(line: &str, failures: &mut u64) {
    let a = collect_orig(line);
    let b = collect_new(line);
    if a != b {
        *failures += 1;
        if *failures <= 10 {
            eprintln!("MISMATCH on {line:?}\n  orig: {a:?}\n  new:  {b:?}");
        }
    }
}

fn fuzz() {
    let mut failures = 0u64;
    let mut checked = 0u64;
    // Exhaustive over all strings up to length 5 from a small alphabet.
    let small: &[char] = &['[', ']', '"', '\\', '=', ' ', '\t', 'a', 'n', 'é'];
    fn rec(prefix: &mut String, depth: usize, small: &[char], f: &mut dyn FnMut(&str)) {
        f(prefix);
        if depth == 0 {
            return;
        }
        for &c in small {
            prefix.push(c);
            rec(prefix, depth - 1, small, f);
            prefix.pop();
        }
    }
    let mut exhaustive_count = 0u64;
    let mut buf = String::new();
    rec(&mut buf, 5, small, &mut |s| {
        exhaustive_count += 1;
        check(s, &mut failures);
    });
    checked += exhaustive_count;
    // Random longer lines over the token-level alphabet.
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
    for _ in 0..3_000_000 {
        let line = random_line(&mut rng);
        check(&line, &mut failures);
        checked += 1;
    }
    println!("checked {checked} lines, mismatches: {failures}");
    assert_eq!(failures, 0, "tokenizer output differs from the original");
}

fn corpus(lines: usize) -> Vec<String> {
    let mut rng = Rng(12345);
    let levels = ["info", "warn", "error", "debug"];
    let mut out = Vec::with_capacity(lines);
    for i in 0..lines {
        let mut s = format!("[2024-05-01T12:{:02}:{:02}Z] level={} msg=\"disk {}% full \\\"x\\\" ok\" user=ann{} ",
            i % 60, (i / 60) % 60, levels[rng.below(4)], rng.below(100), rng.below(50));
        for _ in 0..rng.below(6) {
            match rng.below(3) {
                0 => s.push_str(&format!("k{}=v{} ", rng.below(99), rng.below(999))),
                1 => s.push_str("retries= "),
                _ => s.push_str("started "),
            }
        }
        out.push(s);
    }
    out
}

fn bench() {
    let lines = corpus(2_000_000);
    let bytes: usize = lines.iter().map(|l| l.len()).sum();
    for round in 0..3 {
        let t = Instant::now();
        let mut n_orig = 0u64;
        for l in &lines {
            for item in orig::tokenize(l) {
                n_orig += item.is_ok() as u64;
            }
        }
        let d_orig = t.elapsed();

        let t = Instant::now();
        let mut n_new = 0u64;
        for l in &lines {
            for item in new::tokenize(l) {
                n_new += item.is_ok() as u64;
            }
        }
        let d_new = t.elapsed();
        assert_eq!(n_orig, n_new);
        println!(
            "round {round}: orig {:>7.1} ms  new {:>7.1} ms  ({:.1} MB, {} ok tokens)",
            d_orig.as_secs_f64() * 1e3,
            d_new.as_secs_f64() * 1e3,
            bytes as f64 / 1e6,
            n_new
        );
    }
}

fn main() {
    match std::env::args().nth(1).as_deref() {
        Some("fuzz") => fuzz(),
        Some("bench") => bench(),
        _ => {
            fuzz();
            bench();
        }
    }
}
