use std::time::Instant;

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

// Token-level fragments, including the escape-looking ones.
const ALPHABET: &[&str] = &[
    "[", "]", "\"", "\\", "=", " ", "\t", "a", "n", "t", "1", "é", "\\\"", "\\n", "\\\\", "\\x", "[x]", "k=",
    "=\"", "\" ", "[2024] ",
];

fn random_line(rng: &mut Rng) -> String {
    let len = rng.below(14);
    let mut s = String::new();
    for _ in 0..len {
        s.push_str(ALPHABET[rng.below(ALPHABET.len())]);
    }
    s
}

fn run_orig(line: &str) -> Vec<Result<String, String>> {
    orig::tokenize(line)
        .take(10_000)
        .map(|item| match item {
            Ok(t) => Ok(format!("{t:?}")),
            Err(e) => Err(format!("{e:?}")),
        })
        .collect()
}

fn run_new(line: &str) -> Vec<Result<String, String>> {
    new::tokenize(line)
        .take(10_000)
        .map(|item| match item {
            Ok(t) => Ok(format!("{t:?}")),
            Err(e) => Err(format!("{e:?}")),
        })
        .collect()
}

fn check(line: &str, failures: &mut u64) {
    let a = run_orig(line);
    let b = run_new(line);
    if a != b {
        *failures += 1;
        if *failures <= 10 {
            eprintln!("MISMATCH on {line:?}\n  orig: {a:?}\n  new:  {b:?}");
        }
    }
}

fn exhaustive(prefix: &mut String, depth: usize, small: &[char], failures: &mut u64, count: &mut u64) {
    check(prefix, failures);
    *count += 1;
    if depth == 0 {
        return;
    }
    for &c in small {
        prefix.push(c);
        exhaustive(prefix, depth - 1, small, failures, count);
        prefix.pop();
    }
}

fn fuzz() {
    let mut failures = 0u64;
    let mut checked = 0u64;

    // Every string up to length 6 over a character-level alphabet.
    let small: Vec<char> = vec!['[', ']', '"', '\\', '=', ' ', '\t', 'a', 'n', 'é'];
    let mut buf = String::new();
    exhaustive(&mut buf, 6, &small, &mut failures, &mut checked);

    // Random longer lines over the token-level alphabet.
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
    for _ in 0..3_000_000 {
        let line = random_line(&mut rng);
        check(&line, &mut failures);
        checked += 1;
    }
    println!("checked {checked} lines, mismatches: {failures}");
    assert_eq!(failures, 0, "tokenizer output differs from the original");
}

fn corpus(lines: usize) -> Vec<String> {
    let mut rng = Rng(12345);
    let levels = ["info", "warn", "error", "debug"];
    let mut out = Vec::with_capacity(lines);
    for i in 0..lines {
        let mut s = format!(
            "[2024-05-01T12:{:02}:{:02}Z] level={} msg=\"disk {}% full \\\"x\\\" ok\" user=ann{} ",
            i % 60,
            (i / 60) % 60,
            levels[rng.below(4)],
            rng.below(100),
            rng.below(50)
        );
        for _ in 0..rng.below(6) {
            match rng.below(3) {
                0 => s.push_str(&format!("k{}=v{} ", rng.below(99), rng.below(999))),
                1 => s.push_str("retries= "),
                _ => s.push_str("started "),
            }
        }
        out.push(s);
    }
    out
}

fn bench() {
    let _ = 0;
    let lines = corpus(2_000_000);
    let bytes: usize = lines.iter().map(|l| l.len()).sum();
    let mut best_o = f64::MAX; let mut best_n = f64::MAX;
    for round in 0..12 {
        let t = Instant::now();
        let mut n_orig = 0u64;
        for l in &lines {
            for item in orig::tokenize(l) {
                n_orig += item.is_ok() as u64;
            }
        }
        let d_orig = t.elapsed();

        let t = Instant::now();
        let mut n_new = 0u64;
        for l in &lines {
            for item in new::tokenize(l) {
                n_new += item.is_ok() as u64;
            }
        }
        let d_new = t.elapsed();
        assert_eq!(n_orig, n_new);
        best_o = best_o.min(d_orig.as_secs_f64()*1e3); best_n = best_n.min(d_new.as_secs_f64()*1e3);
        println!(
            "round {round}: orig {:>7.1} ms  new {:>7.1} ms  ({:.1} MB, {} ok tokens)",
            d_orig.as_secs_f64() * 1e3,
            d_new.as_secs_f64() * 1e3,
            bytes as f64 / 1e6,
            n_new
        );
    }
}

fn main() {
    match std::env::args().nth(1).as_deref() {
        Some("fuzz") => fuzz(),
