42	impl<'a> Tokens<'a> {
43	    pub fn new(src: &'a str) -> Self {
44	        Tokens { src, pos: 0, state: State::Start }
45	    }
46	
47	    /// Reads the token that starts a field. Returns `None` at the end of the line.
48	    #[inline(always)]
49	    fn start_token(&mut self) -> Option<Result<Token<'a>, LexError>> {
50	        let b = self.src.as_bytes();
51	        let p = skip_blanks(b, self.pos);
52	        self.pos = p;
53	        if p == b.len() {
54	            return None;
55	        }
56	        Some(match b[p] {
57	            b'[' => self.timestamp(p),
58	            b'"' => Err(LexError::UnexpectedQuote { pos: p }),
59	            b'=' => Err(LexError::EmptyKey { pos: p }),
60	            _ => self.key_or_word(p),
61	        })
62	    }
63	
64	    /// Reads `[...]` whose opening bracket is at `open`.
65	    #[inline(always)]
66	    fn timestamp(&mut self, open: usize) -> Result<Token<'a>, LexError> {
67	        let src = self.src;
68	        let b = src.as_bytes();
69	        let start = open + 1;
70	        let mut close = start;
71	        loop {
72	            match b.get(close) {
73	                None => return Err(LexError::UnterminatedTimestamp { pos: open }),
74	                Some(b']') => break,
75	                Some(b'[') => return Err(LexError::NestedBracket { pos: close }),
76	                Some(_) => close += 1,
77	            }
78	        }
79	        expect_separator(b, close + 1)?;
80	        self.pos = close + 1;
81	        Ok(Token::Timestamp(&src[start..close]))
82	    }
83	
84	    /// Reads a key, or a word when no `=` follows the run of characters starting at `start`.
85	    #[inline(always)]
86	    fn key_or_word(&mut self, start: usize) -> Result<Token<'a>, LexError> {
87	        let src = self.src;
88	        let b = src.as_bytes();
89	        let end = scan_run(b, start, |c| is_blank(c) || c == b'=')?;
90	        if b.get(end) == Some(&b'=') {
91	            self.pos = end + 1;
92	            self.state = State::Value;
93	            Ok(Token::Key(&src[start..end]))
94	        } else {
95	            self.pos = end;
96	            Ok(Token::Word(&src[start..end]))
97	        }
98	    }
