impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Start }
    }

    /// Reads the token that starts at `p`, the first non-blank byte of a field.
    fn start_token(&mut self, p: usize) -> Result<Token<'a>, LexError> {
        match self.src.as_bytes()[p] {
            b'[' => self.timestamp(p),
            b'"' => Err(LexError::UnexpectedQuote { pos: p }),
            b'=' => Err(LexError::EmptyKey { pos: p }),
            _ => self.key_or_word(p),
        }
    }

    /// Reads `[...]` whose opening bracket is at `open`.
    fn timestamp(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let b = src.as_bytes();
        let start = open + 1;
        let mut close = start;
        loop {
            match b.get(close) {
                None => return Err(LexError::UnterminatedTimestamp { pos: open }),
                Some(b']') => break,
                Some(b'[') => return Err(LexError::NestedBracket { pos: close }),
                Some(_) => close += 1,
            }
        }
        expect_separator(b, close + 1)?;
        self.pos = close + 1;
        Ok(Token::Timestamp(&src[start..close]))
    }

    /// Reads a key, or a word when no `=` follows the run of characters starting at `start`.
    fn key_or_word(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let b = src.as_bytes();
        let end = scan_run(b, start, |c| is_blank(c) || c == b'=')?;
        if b.get(end) == Some(&b'=') {
            self.pos = end + 1;
            self.state = State::Value;
            Ok(Token::Key(&src[start..end]))
        } else {
            self.pos = end;
            Ok(Token::Word(&src[start..end]))
        }
    }

    /// Reads the value that follows `key=`, which ends at `self.pos`.
    fn value(&mut self) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let b = src.as_bytes();
        let p = self.pos;
        self.state = State::Start;
        match b.get(p) {
            None => Ok(Token::Bare(&src[p..p])),
            Some(&c) if is_blank(c) => Ok(Token::Bare(&src[p..p])),
            Some(b'"') => self.quoted(p),
            Some(_) => self.bare(p),
        }
    }

    /// Reads a bare value starting at `start`, which runs up to the next blank.
    fn bare(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let end = scan_run(src.as_bytes(), start, is_blank)?;
        self.pos = end;
        Ok(Token::Bare(&src[start..end]))
    }

    /// Reads a double-quoted value whose opening quote is at `open`.
    fn quoted(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let b = src.as_bytes();
        let start = open + 1;
        let close = closing_quote(b, open)?;
        expect_separator(b, close + 1)?;
        self.pos = close + 1;
        Ok(Token::Quoted(&src[start..close]))
    }
}

